        setHits(0);
        setArrowsLeft(maxArrows);
        setProjectiles([]);
        setShowCoupon(false);
        setPhase("playing");
        const newBalloons = Array.from({ length: balloonCount }).map((_, i) => ({
            id: Date.now() + i,
            x: 10 + Math.random() * 80,
            y: -20 - Math.random() * 50,
            speed: 0.16 + Math.random() * 0.25,
            color: COLORS[i % COLORS.length],
            radius: 26 + Math.random() * 10,
            popped: false,
        }));
