  ctaFontWeight?: number;
  ctaFontFamily?: string;
  backgroundColor?: string;
  borderColor?: string;
  showBorder?: boolean;
  textColor?: string;
  navFontSize?: number;
  navGap?: number;
  horizontalPadding?: number;
  headerHeight?: number;
  desktopBreakpoint?: number;
  mobileBreakpoint?: number;
  menuBackground?: string;
